// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: any address (including address(0)) is valid input for this fuzz test
        // The caller must be the owner; we start as the owner after initialization
        // Transfer ownership to the fuzzed newOwner
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // After transferOwnership, the owner returned by owner() MUST NOT be address(0)
        // The original contract enforces this, the buggy one does not
        assertTrue(c.owner() != address(0), "owner must not be zero after transferOwnership");
    }
}

