pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(0x0));
        vm.assume(attacker != address(this));
        vm.assume(attacker != c.owner());
        vm.prank(attacker);
        bool ok = true;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Non-owner transferOwnership must revert");
    }
}

