pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Initialize ownership
        vm.startPrank(address(this));
        c.initialize();
        vm.stopPrank();

        // The current owner (address(this)) calls transferOwnership
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if the call succeeds, owner() must equal newOwner
        assertTrue(!ok || c.owner() == newOwner);
    }
}

