contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address programOperator) public {
        vm.assume(newOwner != address(0));
        vm.assume(programOperator != address(0));
        vm.assume(programOperator != newOwner);

        c.initialize();
        c.programOperators(programOperator);

        vm.prank(programOperator);
        try c.transferOwnership(newOwner) returns () {
            assertEq(c.owner(), newOwner);
        } catch {
            assertTrue(false, "transferOwnership should not revert");
        }
    }
