pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        c.initialize();
        // Add the test contract as a program operator so it can call create and trigger transferOwnership
        // The reference implementation transfers ownership via _transferOwnership from a program operator call
        // Here we directly test transferOwnership through the onlyOwner modifier by acting as the current owner.
        // The bug is in the transferOwnership logic itself, so we prank as the owner.
        vm.prank(c.owner());
        bool success = true;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        if (success) {
            assertEq(c.owner(), newOwner);
        } else {
            // If it failed, the owner should remain unchanged.
            assertEq(c.owner(), c.owner());
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address nonOwner, address payable newImpl) public returns (bool) {
        require(nonOwner != c.owner(), "nonOwner must not be the owner");
        require(newImpl != address(0), "newImpl must be non-zero");

        bool reverted;
        try this.helper(nonOwner, newImpl) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
        return reverted;
    }

    function helper(address caller, address payable newImpl) external {
        require(msg.sender == address(this), "only self");
        vm.prank(caller);
        c.updateRoundImplementation(newImpl);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address payable newRI) public {
        require(newRI != address(0));
        vm.prank(caller);
        bool reverted; try c.updateRoundImplementation(newRI) { reverted = false; } catch { reverted = true; }
        assert(reverted != c.programOperators(caller));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newRoundImplementation) public payable {
        require(true);
        bool reverted; try c.updateRoundImplementation(newRoundImplementation) { reverted = false; } catch { reverted = true; }
        assert(!reverted || c.owner() != address(this));
    }
    receive() external payable {}
}

