pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newRoundImpl) public {
        // initialize the contract to become owner
        c.initialize();
        // vm.prank to ensure onlyOwner passes; we are the owner after initialization
        // owner is address(this) after c.initialize() done in setUp context
        // but to make it explicit we prank as the owner (which is this contract itself after Ownable_init_unchained)
        // Actually state: _owner is set to msg.sender of initialize which is address(this).
        // So we can call updateRoundImplementation directly without prank because we are the owner.
        // But to be safe, we prank ourselves.
        vm.prank(address(this));
        c.updateRoundImplementation(newRoundImpl);
        // The general rule: roundImplementation MUST NOT be zero address after the call.
        bool ok = c.roundImplementation() != address(0);
        assertTrue(ok);
    }
}

