// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newImplementation) public {
        vm.assume(newImplementation != address(0));
        address payable impl = payable(newImplementation);
        c.updateRoundImplementation(impl);
        // The reference contract always sets roundImplementation to the passed non-zero address.
        // The mutated contract first sets it to 0xdead and then overwrites it with the passed address.
        // Therefore, for any non-zero input, the public getter roundImplementation() must return the passed address.
        // However, if the passed address happens to be 0xdead, both versions behave the same.
        // This assertion always holds for the reference, but the mutant also satisfies it for all inputs.
        // The previously tried rules are fundamentally identical to this one.
        // Since the bug writes an intermediate value that is immediately overwritten, no public getter reflects the intermediate state.
        // Thus, no single assertion on the final state of roundImplementation can distinguish the mutant from the reference.
        // The true invariant is that the implementation is never set to 0xdead unless the input is 0xdead, but since the final state is correct,
        // the bug is unobservable through the public interface after the function returns.
        // The only way to observe the bug is during execution, which would require inspecting the event emission order or storage during the call,
        // but the rules forbid using vm.expectEmit or similar cheatcodes.
        // Therefore, a valid fuzz test that passes for the reference and fails for the mutant cannot be constructed under the current constraints.
        // The assertion below is a tautology and will not distinguish the bug.
        assertTrue(c.roundImplementation() == impl, "final address mismatch");
    }
}
